fered":{"@type":"Service","name":"Hurricane & Nor’easter Appraisal","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/hurricane-noreaster-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/burst-pipe-water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow Load & Ice Dam Appraisal","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/snow-load-ice-dam-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/appraisal-umpire-services/"}}]},"description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across New York State.","areaServed":[{"@type":"State","name":"New York"},{"@type":"City","name":"Manhattan"},{"@type":"City","name":"Brooklyn"},{"@type":"City","name":"Queens"},{"@type":"City","name":"Staten Island"},{"@type":"City","name":"Hempstead"},{"@type":"City","name":"Islip"},{"@type":"City","name":"White Plains"},{"@type":"City","name":"Albany"},{"@type":"City","name":"Syracuse"},{"@type":"City","name":"Rochester"},{"@type":"City","name":"Buffalo"},{"@type":"City","name":"Binghamton"}],"priceRange":"$$","knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Xactimate estimating","Ice dam claims","Hurricane deductibles","Co-op and condo claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://newyorkinsuranceappraiser.com/#website","url":"https://newyorkinsuranceappraiser.com/","name":"New York Insurance Appraiser","publisher":{"@id":"https://newyorkinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://newyorkinsuranceappraiser.com/ask-an-appraiser/#webpage","url":"https://newyorkinsuranceappraiser.com/ask-an-appraiser/","name":"Insurance Appraisal FAQ for New York | Costs & Rules","description":"Answers to common New York insurance appraisal questions, grouped by topic: basics, costs, deadlines, state rules and agencies, and working with us.","inLanguage":"en-US","isPartOf":{"@id":"https://newyorkinsuranceappraiser.com/#website"},"about":{"@id":"https://newyorkinsuranceappraiser.com/#business"},"publisher":{"@id":"https://newyorkinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","primaryImageOfPage":{"@type":"ImageObject","url":"https://newyorkinsuranceappraiser.com/assets/img/photos/livingroom.webp","width":1024,"height":683},"breadcrumb":{"@id":"https://newyorkinsuranceappraiser.com/ask-an-appraiser/#breadcrumb"},"mainEntity":{"@id":"https://newyorkinsuranceappraiser.com/ask-an-appraiser/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://newyorkinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Ask an appraiser","item":"https://newyorkinsuranceappraiser.com/ask-an-appraiser/"}],"@id":"https://newyorkinsuranceappraiser.com/ask-an-appraiser/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is an insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"It is a procedure in most property policies for settling disagreements over the amount of a covered loss. Each side names an appraiser, the appraisers choose an umpire, and an award signed by any two of the three sets the amount."}},{"@type":"Question","name":"Is an insurance appraiser the same as a real estate appraiser?","acceptedAnswer":{"@type":"Answer","text":"No. A real estate appraiser estimates market value for a sale or mortgage. An insurance appraiser values the cost to repair or replace damaged property under the terms of an insurance policy."}},{"@type":"Question","name":"Can appraisal decide whether my claim is covered?","acceptedAnswer":{"@type":"Answer","text":"Generally not. Appraisal decides the amount of loss, while coverage questions are usually for the insurer, DFS complaints or a court. If your claim was denied outright, talk to a New York attorney."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Under the New York standard form and most policies modeled on it, either the policyholder or the insurer can demand appraisal in writing. Check your policy for any conditions that come first."}},{"@type":"Question","name":"Is the appraisal award binding?","acceptedAnswer":{"@type":"Answer","text":"Under the standard form, an award signed by two of the three panel members determines the amount of loss. Courts may set an award aside only in limited situations, such as fraud or a panel exceeding its authority."}},{"@type":"Question","name":"Who pays for the appraisal?","acceptedAnswer":{"@type":"Answer","text":"Under the standard form, each side pays its own appraiser, and the umpire’s fee and other appraisal expenses are shared equally. Your policy may word this differently, so check it."}},{"@type":"Question","name":"How are appraiser fees structured?","acceptedAnswer":{"@type":"Answer","text":"Arrangements vary and can include hourly, flat or other fee structures. Some carriers question whether an appraiser paid on a percentage of the award is disinterested, so ask how any appraiser is paid and get it in writing."}},{"@type":"Question","name":"Is appraisal worth it for a small difference?","acceptedAnswer":{"@type":"Answer","text":"Sometimes not. When the gap is modest, appraiser and umpire fees can absorb much of the increase. Our settlement gap and fee estimator can help you test the numbers before you decide."}},{"@type":"Question","name":"Can I recover my appraisal costs from the insurer?","acceptedAnswer":{"@type":"Answer","text":"Generally, appraisal does not shift fees to the other side. Whether any costs are recoverable in a particular situation is a legal question for a New York attorney."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"It depends on the size of the loss and how quickly both appraisers engage. Simple residential disputes can resolve in weeks, while complex or commercial claims can take several months."}},{"@type":"Question","name":"Is there a deadline to demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Some policies set one and many do not, but other deadlines still apply. Many New York property policies limit lawsuits to two years from the loss, so check your policy and talk to an attorney if that date is near."}},{"@type":"Question","name":"Does appraisal stop the suit-limitation clock?","acceptedAnswer":{"@type":"Answer","text":"Not necessarily. Whether appraisal pauses a contractual deadline depends on the policy and the circumstances, so do not assume it does. Ask a New York attorney."}},{"@type":"Question","name":"How long do the appraisers have to pick an umpire?","acceptedAnswer":{"@type":"Answer","text":"The New York standard form gives them 15 days, after which either party can ask a judge to appoint one. Your policy may use similar or different time frames."}},{"@type":"Question","name":"Who regulates insurers in New York?","acceptedAnswer":{"@type":"Answer","text":"The New York State Department of Financial Services (DFS) licenses insurers and public adjusters and accepts consumer complaints. Its claim-handling standards are found in Regulation 64."}},{"@type":"Question","name":"What is the New York Standard Fire Policy?","acceptedAnswer":{"@type":"Answer","text":"It is the statutory fire policy form set out in Insurance Law §3404, adopted in 1943. Its appraisal provision became the model for the appraisal clauses in most U.S. property policies."}},{"@type":"Question","name":"What is NYPIUA?","acceptedAnswer":{"@type":"Answer","text":"The New York Property Insurance Underwriting Association is the state’s FAIR Plan, a residual market insurer for property owners who cannot find coverage in the regular market. Its policies have their own terms, so read the appraisal wording in yours."}},{"@type":"Question","name":"Does a homeowners policy cover flood in New York?","acceptedAnswer":{"@type":"Answer","text":"Generally no. Flood is excluded from standard homeowners policies; flood coverage usually comes from the National Flood Insurance Program or a private flood policy, each with its own terms."}},{"@type":"Question","name":"Can I file a complaint about how my claim is being handled?","acceptedAnswer":{"@type":"Answer","text":"Yes, DFS accepts consumer complaints about insurers. A complaint is separate from appraisal and does not set the amount of loss."}},{"@type":"Question","name":"Are you a law firm or public adjuster?","acceptedAnswer":{"@type":"Answer","text":"No. We are independent insurance appraisers. We do not give legal advice and we do not act as public adjusters; our work focuses on valuing the amount of loss."}},{"@type":"Question","name":"Do you work for insurance companies?","acceptedAnswer":{"@type":"Answer","text":"When you retain us as your appraiser, we work for you. We may also serve as neutral umpires, and in that role we work for neither side."}},{"@type":"Question","name":"Where in New York do you work?","acceptedAnswer":{"@type":"Answer","text":"We take appraisal assignments across New York State, from the five boroughs and Long Island to the Hudson Valley, Capital Region, Central New York and Western New York."}},{"@type":"Question","name":"What should I send for an initial review?","acceptedAnswer":{"@type":"Answer","text":"Your policy and declarations page, the carrier’s estimate and payment letters, any contractor estimate, and photos of the damage. That is usually enough for us to tell you whether appraisal looks worth pursuing."}},{"@type":"Question","name":"How do I get started?","acceptedAnswer":{"@type":"Answer","text":"Call +1 (844) 537-1427 or email info@newyorkinsuranceappraiser.com, Monday to Friday, 8am to 6pm ET. We will explain our fee arrangement in writing before you decide anything."}}],"@id":"https://newyorkinsuranceappraiser.com/ask-an-appraiser/#faq"}]}</script>
</head>
